import{_ as r,h as i,i as e,c as s,v as t,p as n,x as o,m as p,e as h,S as d}from"./chunks/framework.Dvtg8yj2.js";const f=JSON.parse('{"title":"结果监督","description":"","frontmatter":{"title":"结果监督","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/outcome-supervision.md","filePath":"llm/outcome-supervision.md","lastUpdated":1788454257000}'),m={name:"llm/outcome-supervision.md"};function c(u,a,E,_,A,b){const l=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="结果监督" tabindex="-1">结果监督 <a class="header-anchor" href="#结果监督" aria-label="Permalink to &quot;结果监督&quot;">​</a></h1><div class="epigraph"><p>只看最终答案对不对、测试过不过、人喜不喜欢整段回复，监督最便宜，但把功劳和过错整段算在一条轨迹头上。</p><footer>—— Uesato 等，Solving math word problems with process- and outcome-based feedback，2022；Lightman 等，Let&#39;s Verify Step by Step</footer></div><p>推理任务的标注可以停在终点：数学题的数字、代码的单测、对话的整体偏好。这种只对完整输出给标量的做法叫结果监督（outcome supervision）。它与偏好对、与 <a href="/llm/process-supervision">过程监督</a> 共享「用反馈改策略」这一目的，但信用分配完全不同：过程监督给每一步对错，结果监督只给终点。Uesato 等人在数学应用题上系统比较了过程反馈与结果反馈；Lightman 等人在 MATH 上把结果奖励模型（ORM）和过程奖励模型（PRM）对照，作为验证器去挑 Best-of-N。本篇只写结果这一端：它监督什么、梯度从哪回传、何时够用、何时会奖到错误推理。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一条解答 \\(y=(s_1,\\ldots,s_T,a)\\) 里，\\(a\\) 是最终答案，\\(s_t\\) 是中间步骤。结果标签 \\(\\ell\\) 是 \\(a\\) 是否等于金标准、单测是否全绿、或人是否接受整段 \\(y\\)。训练 ORM 就是拟合 \\(p(\\ell=1\\mid x,y)\\)；拿它当奖励做 RL，或当验证器给候选打分，都只用这一个标量。便宜之处是标签可自动：数学对答案、竞赛编程对评测机、二元偏好对整段比较。贵的是信用：\\(\\ell=1\\) 时，所有 \\(s_t\\) 都被当成有功；\\(\\ell=0\\) 时，所有 \\(s_t\\) 都被当成有过。第一步就错、后面用错公式碰巧得到对的数字，结果监督会当成正例。</p><p>Uesato 等人指出，结果反馈足以让模型在应用题上提高最终正确率，同时也能学到「错的推导 + 对的答案」这类捷径。问题不是结果标签假，而是标签的支撑太粗，与轨迹内部的真假无关。若下游只用最终数字计分，捷径在指标上是合法的；若下游要可读的证明、可维护的代码、可审计的医疗建议，捷径是事故。</p><h3 id="结果奖励模型在学什么" tabindex="-1">结果奖励模型在学什么 <a class="header-anchor" href="#结果奖励模型在学什么" aria-label="Permalink to &quot;结果奖励模型在学什么&quot;">​</a></h3><p>ORM 的输入是完整 \\((x,y)\\)，输出一个标量或正确概率。它没有逐步对齐的标注，只能从终点反推哪些表面特征相关。数据里「对的答案常常更长、带有检查句、带有 \\boxed{}」时，ORM 会给这些格式加分，哪怕推理是空的。数据里「错的答案常在某类代数上失败」时，它可能学到题目类型而非推理质量。作为验证器，ORM 在 Best-of-N 增大时会饱和：更多候选意味着更多「错推理、对答案」或「看起来像对的错答案」，结果分数把它们排到前面。Lightman 等人用这一点对照 PRM：过程分数随 \\(N\\) 仍能继续涨，ORM 先涨后平台。</p><p><span class="marginnote">结果监督不等于只能做人标。单测、编译器、计算器、形式验证器都是结果预言机。预言机越硬，捷径空间越小：编程单测比「答案是 42」更难骗，但仍可能用硬编码分支骗过有限测试。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>结果监督的训练数据是 \\((x,y,\\ell)\\)，\\(\\ell\\) 来自自动检查或整段人评。三条用法应分开写，不要混成一个「强化学习」。</p><p><strong>直接过滤。</strong> 从模型或教师采样多条 \\(y\\)，只保留 \\(\\ell=1\\) 的做 SFT。这是最常见的结果监督：拒绝采样微调、自洽后再用答案一致性筛选，都属此类。没有奖励模型，没有逐步标签。</p><p><strong>结果奖励模型。</strong> 用 \\(\\ell\\) 训一个分类器或回归器 \\(R_\\phi(x,y)\\)，再在候选集上 argmax，或塞进 PPO / 拒绝采样。Lightman 等人的 ORM 就是这一支，用作验证器而不是在线 RL 的唯一故事。</p><p><strong>结果标量进 RL。</strong> 整段生成结束后给一个奖励，用策略梯度更新。信用分配靠价值函数或蒙特卡洛：中间 token 的优势来自终点回报的折现，方差大。Uesato 等人比较的 outcome-based feedback 包含这一支。</p> \\[R_{\\mathrm{out}}(x,y)=\\mathbb{I}\\bigl[\\mathrm{check}(a)=\\text{gold}\\bigr] \\quad\\text{或}\\quad R_\\phi(x,y)\\approx p(\\ell=1\\mid x,y). \\]<p>检查函数 \\(\\mathrm{check}\\) 必须与评测一致：数学要统一分数形式与容差，代码要同一套隐藏测试，对话则几乎没有可靠 \\(\\mathrm{check}\\)，只能退回人或偏好模型——那已经是整段偏好，不是数学意义上的对错。</p>',16)),(e(),n(d,null,{default:o(()=>[h(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E9%A2%98%E7%9B%AE%20x%22%5D%20--%3E%20GEN%5B%22%E5%AE%8C%E6%95%B4%E8%BD%A8%E8%BF%B9%20y%22%5D%0A%20%20GEN%20--%3E%20A%5B%22%E6%9C%80%E7%BB%88%E7%AD%94%E6%A1%88%20%2F%20%E7%A8%8B%E5%BA%8F%20%2F%20%E6%95%B4%E6%AE%B5%E5%9B%9E%E5%A4%8D%22%5D%0A%20%20A%20--%3E%20CHK%5B%22%E6%A3%80%E6%9F%A5%E5%99%A8%E6%88%96%E4%BA%BA%22%5D%0A%20%20CHK%20--%3E%20L%5B%22%E6%A0%87%E9%87%8F%20%E2%84%93%22%5D%0A%20%20L%20--%3E%20FILT%5B%22%E8%BF%87%E6%BB%A4%E5%90%8E%20SFT%22%5D%0A%20%20L%20--%3E%20ORM%5B%22%E8%AE%AD%E7%BB%83%20ORM%22%5D%0A%20%20L%20--%3E%20RL%5B%22%E7%BB%88%E7%82%B9%E5%A5%96%E5%8A%B1%20RL%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="与成对偏好的关系" tabindex="-1">与成对偏好的关系 <a class="header-anchor" href="#与成对偏好的关系" aria-label="Permalink to &quot;与成对偏好的关系&quot;">​</a></h3><p>偏好优化里的 \\(y_w\\succ y_l\\) 常常也是结果级：人看完整回答再选。它比「对错」细——文风、安全、格式都会进序——但仍然不指出哪一句错。数学竞赛上，对错是比偏好更干净的结果信号；开放对话上，对错未定义，结果监督就是偏好或 RM。不要把 DPO 数据自动当成过程标签，也不要把 MATH 的对错自动当成人类偏好。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h3 id="稀疏回报如何变成错误归因" tabindex="-1">稀疏回报如何变成错误归因 <a class="header-anchor" href="#稀疏回报如何变成错误归因" aria-label="Permalink to &quot;稀疏回报如何变成错误归因&quot;">​</a></h3><p>策略梯度把终点回报赋给轨迹上每一个 token。若早期 token 决定了推理分支、晚期 token 只是把数字抄进框里，梯度并不知道这一点：所有位置共享同一个 \\(R\\)。方差表现为：同样的错误开头，有时因算术巧合拿正回报，有时拿零，更新噪声大。价值函数（critic）可以降低方差，但不能发明过程信息——它仍在拟合终点回报的期望。这就是为何结果 RL 能提高正确率，却不稳定地提高「可验证的中间推理」。</p><p>ORM 作为验证器时，机制是重排序而不是逐步剪枝。必须把 \\(N\\) 条完整轨迹都生成完再打分，计算浪费在已经错了的前缀上。\\(N\\) 增大，覆盖到正确答案的机会增加，也覆盖到欺骗 ORM 的机会。饱和来自验证器误差，不是来自生成器没有更好的样本。</p><p><span class="marginnote">自洽（多数表决）是结果监督的解码技巧：同一题采多条，按最终答案投票。它不检查过程，会把「同一类系统性错误」投成赢家。投票一致不等于步骤正确。</span></p><h3 id="捷径与可验证性" tabindex="-1">捷径与可验证性 <a class="header-anchor" href="#捷径与可验证性" aria-label="Permalink to &quot;捷径与可验证性&quot;">​</a></h3><p>结果检查越容易被无关相关骗过，捷径越多。整数答案、短字符串匹配最容易出现「错步骤、对终点」。代码加隐藏测试会好一些，仍怕针对测试的特解。开放式写作几乎不可自动结果监督，除非把「人打分」当结果——成本立刻接近过程标注。选择结果监督，等于选择「评测机定义的任务」。把同一套终点奖励套到需要逐步忠实的领域，是机制误用。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>结果监督的优点是吞吐：自动检查可以给百万级轨迹打标，支撑拒绝采样与大规模 RL。缺点是过程不可审计、Best-of-N 用 ORM 会饱和、信用稀疏。工程上应把检查器当成产品契约：版本、容差、超时、是否泄漏测试。检查器一改，所有历史 \\(\\ell\\) 作废，ORM 要重训。</p><p>与过程监督的分工：最终指标只关心答案、中间步骤不展示给用户、检查器很硬，结果监督够用。步骤要展示、要搜索中途剪枝、要避免「蒙对」，上 PRM。Uesato 与 Lightman 都不是说结果无用，而是说它回答的是另一个问题。混合很常见：过滤用结果，验证用过程，RL 的稠密奖励用逐步，终点再用检查器门控——门控仍是结果监督，只是不再单独承担归因。</p><p><span class="marginnote">不要用 ORM 的分数当逐步奖励去喂每一步。把整段标量复制到每个 token 上，只是把稀疏回报变成长度偏置：更长的错解会累积更多负分或更多正分，取决于你怎么广播。</span></p><h3 id="何时不必上结果监督" tabindex="-1">何时不必上结果监督 <a class="header-anchor" href="#何时不必上结果监督" aria-label="Permalink to &quot;何时不必上结果监督&quot;">​</a></h3><p>没有自动检查器、人又只能标整段好坏，那是偏好优化，不必硬造一个「对错」。已经有逐步标签或可靠的逐步检查，直接走 <a href="/llm/process-supervision">过程监督</a> 与 <a href="/llm/step-level-verify">逐步验证</a>。检查器会泄漏标准答案到提示模板里时，先修模板，否则结果监督在训练泄漏上刷分。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>结果监督只给完整输出一个标量：对错、单测、整段偏好，标签便宜，信用粗糙。</li><li>用法分三条：按结果过滤 SFT、训 ORM 做验证、把终点奖励送进 RL。</li><li>ORM 作 Best-of-N 验证器会随 \\(N\\) 饱和，因其无法区分错推理与对答案。</li><li>稀疏回报把终点功过摊到整条轨迹，促成捷径与高方差。</li><li>检查器必须与评测同版本；它定义任务，也定义可被欺骗的面。</li><li>步骤要可审计或要中途剪枝时，结果监督不够，应接到 PRM。</li><li>出处：Uesato 等，<em>Solving math word problems with process- and outcome-based feedback</em>，2022；Lightman 等，<em>Let&#39;s Verify Step by Step</em> 中对 ORM 的对照。</li></ul>',17))])}const R=r(m,[["render",c]]);export{f as __pageData,R as default};
